import { orderedLayers } from "./layers.mjs";
export function resolveConfig(layers) {
  const config = {};
  for (const layer of orderedLayers(layers)) {
    for (const key of Object.getOwnPropertyNames(layer.values)) {
      Object.defineProperty(config, key, {
        value:layer.values[key], enumerable:true, writable:true, configurable:true
      });
    }
  }
  return config;
}

